#!/usr/bin/env python3
# gen_src.py — 生成标准化 C++ 编译负载
# 【重要】本脚本的参数与内容结构在全部待测系统上必须完全一致。
#         严禁修改 FILE_COUNT / 循环次数 / 随机性（本脚本不含任何随机数）。
#         目的是让"编译耗时"只反映系统差异，不反映负载差异。
#
# 用法：python3 scripts/02-compile/gen_src.py [输出目录，默认 ./bench-src]
# 产出：src000.cpp … src149.cpp + Makefile

import os
import sys

FILE_COUNT = 150
LOOP_ITERS = 2000
SORT_ELEMS = 10000

TEMPLATE = """\
// src{idx:03d}.cpp — AUTO-GENERATED by gen_src.py (FILE_COUNT={n}, LOOP={loop}, SORT={sort})
// DO NOT EDIT: 修改本文件会破坏跨系统可比性。
#include <vector>
#include <deque>
#include <algorithm>
#include <numeric>
#include <functional>
#include <string>
#include <map>
#include <cstdint>

// 1) 模板类 + 8 个显式实例化（模板实例化是编译耗时的主要来源）
template <typename T>
struct Bench{idx:03d} {{
    T acc;
    Bench{idx:03d}() : acc(T(0)) {{}}
    void fma(T a, T b) {{ acc += a * b + T({idx}); }}
    T scaled(T k) const {{ return acc * k + T({idx} % 13); }}
    T get() const {{ return acc; }}
}};
template struct Bench{idx:03d}<float>;
template struct Bench{idx:03d}<double>;
template struct Bench{idx:03d}<long double>;
template struct Bench{idx:03d}<int>;
template struct Bench{idx:03d}<unsigned int>;
template struct Bench{idx:03d}<long long>;
template struct Bench{idx:03d}<short>;
template struct Bench{idx:03d}<unsigned char>;

// 第二个模板：带 std::function 与 std::map，加重头文件展开与实例化开销
template <typename K, typename V>
struct Map{idx:03d} {{
    std::map<K, V> m;
    std::function<V(K)> f;
    Map{idx:03d}() : f([](K k) {{ return V(k) + V(1); }}) {{}}
    void fill(int n) {{ for (int i = 0; i < n; ++i) m[K(i + {idx})] = f(K(i)); }}
    V sum() const {{ V s = V(0); for (auto const& kv : m) s += kv.second; return s; }}
}};
template struct Map{idx:03d}<int, double>;
template struct Map{idx:03d}<long long, long long>;

// 2) 3 个 {loop} 次迭代的浮点乘加循环
static double loop{idx:03d}_0() {{
    double s = 1.0 + ({idx} % 97) * 0.001;
    for (int k = 0; k < {loop}; ++k) {{
        s = s * 1.0000001 + 0.5 - s * 0.0000002;
        s += (k % 7) * 1e-9;
    }}
    return s;
}}
static double loop{idx:03d}_1() {{
    double s = 2.0 + ({idx} % 89) * 0.002;
    for (int k = 0; k < {loop}; ++k) {{
        s = s * 0.9999999 + 0.25 + s * 0.0000003;
        s -= (k % 11) * 1e-9;
    }}
    return s;
}}
static long double loop{idx:03d}_2() {{
    long double s = 3.0L + ({idx} % 83) * 0.003L;
    for (int k = 0; k < {loop}; ++k) {{
        s = s * 1.00000001L - 0.125L;
        s += (k % 13) * 1e-10L;
    }}
    return s;
}}

// 3) 3 次 std::sort（每次 {sort} 个 int）+ 一次 deque 排序
static long long sortsum{idx:03d}() {{
    std::vector<int> v({sort});
    for (int k = 0; k < {sort}; ++k) v[k] = (k * 31 + {idx} * 17) % 100003;
    std::sort(v.begin(), v.end());
    long long s1 = std::accumulate(v.begin(), v.end(), 0LL);

    std::vector<int> v2({sort});
    for (int k = 0; k < {sort}; ++k) v2[k] = (k * 17 + {idx} * 31) % 100003;
    std::sort(v2.begin(), v2.end(), std::greater<int>());
    long long s2 = std::accumulate(v2.begin(), v2.end(), 0LL);

    std::deque<int> d({sort});
    for (int k = 0; k < {sort}; ++k) d[k] = (k * 7 + {idx}) % 99991;
    std::sort(d.begin(), d.end());
    long long s3 = std::accumulate(d.begin(), d.end(), 0LL);

    return s1 ^ s2 ^ s3;
}}

// 4) 字符串与容器操作，加重 STL 头文件实例化
static std::string str{idx:03d}() {{
    std::string s;
    for (int k = 0; k < 200; ++k) s += char('a' + ((k + {idx}) % 26));
    std::sort(s.begin(), s.end());
    return s;
}}

// 外部符号，防止被优化掉
double sink{idx:03d}();
double sink{idx:03d}() {{
    Bench{idx:03d}<double> b;
    b.fma(0.5, 2.0);
    Map{idx:03d}<int, double> mp;
    mp.fill(64);
    return loop{idx:03d}_0() + loop{idx:03d}_1() + double(loop{idx:03d}_2())
         + double(sortsum{idx:03d}() % 1000)
         + double(str{idx:03d}().size())
         + b.scaled(2.0) + mp.sum();
}}
"""

MAKEFILE = """\
# AUTO-GENERATED — CXXFLAGS 只允许 -O2
# 严禁添加 -march / -mtune / -O3：那会把"发行的编译优化差异"人为放大，
# 而本测试的目的是比较同一份负载在不同系统上的构建速度，不是比较编译器调优。
CXX      ?= g++
CXXFLAGS ?= -O2

SRCS := $(wildcard src*.cpp)
OBJS := $(SRCS:.cpp=.o)

all: $(OBJS)

%.o: %.cpp
\t$(CXX) $(CXXFLAGS) -c $< -o $@

clean:
\trm -f $(OBJS)

.PHONY: all clean
"""


def main():
    out = sys.argv[1] if len(sys.argv) > 1 else "bench-src"
    os.makedirs(out, exist_ok=True)
    total = 0
    for i in range(FILE_COUNT):
        p = os.path.join(out, "src%03d.cpp" % i)
        content = TEMPLATE.format(idx=i, n=FILE_COUNT, loop=LOOP_ITERS, sort=SORT_ELEMS)
        with open(p, "w", encoding="utf-8") as f:
            f.write(content)
        total += len(content.encode("utf-8"))
    with open(os.path.join(out, "Makefile"), "w", encoding="utf-8") as f:
        f.write(MAKEFILE)
    print("生成目录   : %s" % os.path.abspath(out))
    print("文件数量   : %d" % FILE_COUNT)
    print("总字节数   : %d (%.2f MB)" % (total, total / 1048576.0))
    print("循环次数   : %d / 文件" % LOOP_ITERS)
    print("排序元素   : %d / 文件" % SORT_ELEMS)
    print("编译命令   : cd %s && time make -j$(nproc)   （每次前先 make clean）" % out)


if __name__ == "__main__":
    main()
